def comps(g):
    seen=[[False]*len(r) for r in g]; out=[]
    H,W=len(g),len(g[0])
    for i in range(H):
        for j in range(W):
            if not seen[i][j]:
                st=[(i,j)]; c=g[i][j]; cells=[]
                seen[i][j]=True
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and not seen[x][y] and g[x][y]==c:
                            seen[x][y]=True; st.append((x,y))
                out.append((c,cells))
    return out
